// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {IBopAmm} from "./IBopAmm.sol";
import {IBopAmmFallbackAdapter} from "./IBopAmmFallbackAdapter.sol";
import {IBopAmmRouter} from "./IBopAmmRouter.sol";

interface IWETH {
    function deposit() external payable;
    function withdraw(uint256 amount) external;
}

contract BopAmmRouter is IBopAmmRouter, Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    uint256 internal constant BPS_DENOMINATOR = 10_000;
    uint256 internal constant MAX_INTEGRATOR_FEE_BPS = 1_000;

    address public constant NATIVE_ETH = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;

    IBopAmm public immutable bopAmm;
    address public immutable WETH;

    mapping(address => bool) public allowedAdapters;
    address public feeReceiver;
    uint256 public feePercentage;

    modifier onlySelf() {
        if (msg.sender != address(this)) revert OnlySelf();
        _;
    }

    constructor(address _owner, IBopAmm _bopAmm, address _weth) Ownable(_owner) {
        bopAmm = _bopAmm;
        WETH = _weth;
        feeReceiver = _owner;
        feePercentage = 0;
    }

    receive() external payable {
        if (msg.sender != WETH) revert InvalidMsgValue();
    }

    function setAdapter(address adapter, bool allowed) external onlyOwner {
        allowedAdapters[adapter] = allowed;
        emit AdapterUpdated(adapter, allowed);
    }

    function setFeeReceiver(address newFeeReceiver) external onlyOwner {
        if (newFeeReceiver == address(0)) revert InvalidFeeReceiver();
        feeReceiver = newFeeReceiver;
        emit FeeReceiverUpdated(newFeeReceiver);
    }

    function setFeePercentage(uint256 newFeePercentage) external onlyOwner {
        if (newFeePercentage > BPS_DENOMINATOR) revert InvalidFee();
        feePercentage = newFeePercentage;
        emit FeePercentageUpdated(newFeePercentage);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function swapWithAllowance(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline,
        uint256 fee
    ) external payable nonReentrant whenNotPaused returns (uint256 amountOut) {
        if (block.timestamp > deadline) revert Expired();
        _decodeFee(fee);
        (address normalizedIn, address normalizedOut) = _validateAndNormalize(tokenIn, tokenOut);

        _collectInputTo(tokenIn, normalizedIn, amountIn, address(bopAmm));
        uint256 gross = bopAmm.swap(normalizedIn, normalizedOut, amountIn, 0, address(this), deadline);
        amountOut = _finishOutput(tokenOut, normalizedOut, gross, minAmountOut, recipient, fee);
    }

    function swapWithFallback(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline,
        address adapter,
        bytes calldata adapterData,
        uint256 fee
    ) external payable nonReentrant whenNotPaused returns (uint256 amountOut, bool usedFallback) {
        if (block.timestamp > deadline) revert Expired();
        if (!allowedAdapters[adapter]) revert AdapterNotAllowed(adapter);
        _decodeFee(fee);
        (address normalizedIn, address normalizedOut) = _validateAndNormalize(tokenIn, tokenOut);

        _validateMsgValue(tokenIn, amountIn);

        try this.executeBopAmmSwap(
            msg.sender, tokenIn, normalizedIn, normalizedOut, amountIn, minAmountOut, deadline, fee
        ) returns (
            uint256 netOut
        ) {
            _deliverOutput(tokenOut, normalizedOut, recipient, netOut);
            amountOut = netOut;
            usedFallback = false;
        } catch {
            address fallbackRecipient = tokenOut == NATIVE_ETH ? address(this) : recipient;
            uint256 preRefundBalance = IERC20(normalizedIn).balanceOf(address(this));
            _collectInputTo(tokenIn, normalizedIn, amountIn, adapter);
            uint256 gross = IBopAmmFallbackAdapter(adapter)
                .executeFallback(normalizedIn, normalizedOut, amountIn, fallbackRecipient, address(this), adapterData);
            uint256 refunded = _refundResidualInput(tokenIn, normalizedIn, preRefundBalance, msg.sender);
            if (gross < minAmountOut) revert IBopAmm.InsufficientOutput();
            if (tokenOut == NATIVE_ETH) _deliverOutput(tokenOut, normalizedOut, recipient, gross);
            amountOut = gross;
            usedFallback = true;
            emit SwapFallback(msg.sender, adapter, normalizedIn, normalizedOut, amountIn - refunded, amountOut);
        }
    }

    function executeBopAmmSwap(
        address payer,
        address originalTokenIn,
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        uint256 deadline,
        uint256 fee
    ) external onlySelf returns (uint256 amountOut) {
        if (originalTokenIn == NATIVE_ETH) {
            IWETH(WETH).deposit{value: amountIn}();
            IERC20(tokenIn).safeTransfer(address(bopAmm), amountIn);
        } else {
            IERC20(tokenIn).safeTransferFrom(payer, address(bopAmm), amountIn);
        }
        uint256 gross = bopAmm.swap(tokenIn, tokenOut, amountIn, 0, address(this), deadline);
        amountOut = _applyFee(tokenOut, gross, fee);
        if (amountOut < minAmountOut) revert IBopAmm.InsufficientOutput();
    }

    function _validateAndNormalize(address tokenIn, address tokenOut)
        internal
        view
        returns (address normalizedIn, address normalizedOut)
    {
        normalizedIn = tokenIn == NATIVE_ETH ? WETH : tokenIn;
        normalizedOut = tokenOut == NATIVE_ETH ? WETH : tokenOut;
        if (normalizedIn == normalizedOut) revert InvalidPair();
    }

    function _validateMsgValue(address originalTokenIn, uint256 amountIn) internal view {
        if (originalTokenIn == NATIVE_ETH) {
            if (msg.value != amountIn) revert InvalidMsgValue();
        } else {
            if (msg.value != 0) revert InvalidMsgValue();
        }
    }

    function _collectInputTo(address originalTokenIn, address tokenIn, uint256 amountIn, address recipient) internal {
        _collectInputTo(msg.sender, originalTokenIn, tokenIn, amountIn, recipient);
    }

    function _collectInputTo(
        address payer,
        address originalTokenIn,
        address tokenIn,
        uint256 amountIn,
        address recipient
    ) internal {
        _validateMsgValue(originalTokenIn, amountIn);
        if (originalTokenIn == NATIVE_ETH) {
            IWETH(WETH).deposit{value: amountIn}();
            IERC20(tokenIn).safeTransfer(recipient, amountIn);
        } else {
            IERC20(tokenIn).safeTransferFrom(payer, recipient, amountIn);
        }
    }

    function _finishOutput(
        address originalTokenOut,
        address tokenOut,
        uint256 grossOut,
        uint256 minAmountOut,
        address recipient,
        uint256 fee
    ) internal returns (uint256 netOut) {
        netOut = _applyFee(tokenOut, grossOut, fee);
        if (netOut < minAmountOut) revert IBopAmm.InsufficientOutput();
        _deliverOutput(originalTokenOut, tokenOut, recipient, netOut);
    }

    function _applyFee(address token, uint256 amountOut, uint256 fee) internal returns (uint256 netToRecipient) {
        (address feeRecipient, uint256 feeBps) = _decodeFee(fee);
        if (feeBps == 0) return amountOut;

        uint256 feeTotal = amountOut * feeBps / BPS_DENOMINATOR;
        if (feeTotal == 0) return amountOut;

        uint256 protocolFee = feeTotal * feePercentage / BPS_DENOMINATOR;
        uint256 integratorFee = feeTotal - protocolFee;

        if (protocolFee > 0) IERC20(token).safeTransfer(feeReceiver, protocolFee);
        if (integratorFee > 0) IERC20(token).safeTransfer(feeRecipient, integratorFee);

        emit FeeCharged(token, feeRecipient, integratorFee, protocolFee);
        netToRecipient = amountOut - feeTotal;
    }

    function _decodeFee(uint256 fee) internal pure returns (address feeRecipient, uint256 feeBps) {
        feeRecipient = address(uint160(fee));
        feeBps = fee >> 160;
        if (feeBps > MAX_INTEGRATOR_FEE_BPS) revert InvalidFee();
        if (feeBps != 0 && feeRecipient == address(0)) revert InvalidFee();
    }

    function _deliverOutput(address originalTokenOut, address tokenOut, address recipient, uint256 amount) internal {
        if (amount == 0) return;
        if (originalTokenOut == NATIVE_ETH) {
            IWETH(WETH).withdraw(amount);
            (bool ok,) = recipient.call{value: amount}("");
            if (!ok) revert EthTransferFailed();
        } else {
            IERC20(tokenOut).safeTransfer(recipient, amount);
        }
    }

    function _refundResidualInput(
        address originalTokenIn,
        address tokenIn,
        uint256 preRefundBalance,
        address refundRecipient
    ) internal returns (uint256 refund) {
        uint256 postRefundBalance = IERC20(tokenIn).balanceOf(address(this));
        if (postRefundBalance <= preRefundBalance) return 0;

        refund = postRefundBalance - preRefundBalance;
        if (originalTokenIn == NATIVE_ETH) {
            IWETH(WETH).withdraw(refund);
            (bool ok,) = refundRecipient.call{value: refund}("");
            if (!ok) revert EthTransferFailed();
        } else {
            IERC20(tokenIn).safeTransfer(refundRecipient, refund);
        }
    }
}

