// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IPropAMM} from "./IPropAMM.sol";

interface IBopAmm {
    // --- Events ---
    // Successful swaps emit IPropAMM.Swapped (which carries `recipient`).
    event MakerFill(
        uint8 indexed makerId, address indexed tokenIn, address indexed tokenOut, uint256 amountIn, uint256 amountOut
    );

    // --- Errors ---
    error Expired();
    error InsufficientOutput();
    error InvalidPair();
    error TransferFailed();
    error InvalidMakerHook(uint8 makerId);
    /// `rescueEth` transfer failed.
    error EthTransferFailed();
    /// IPropAMM push-payment swap. The caller must transfer `amountIn` of
    /// `tokenIn` to BopAmm before calling.
    function swap(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline
    ) external returns (uint256 amountOut);

    /// Flash-style swap. BopAmm delivers `tokenOut` first, then calls
    /// `msg.sender.bopAmmSwapCallback(...)`; the callback must provide enough
    /// `tokenIn` for maker payment before the function returns.
    function swapWithCallback(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline,
        bytes calldata callbackData
    ) external returns (uint256 amountOut);

    function quote(address tokenIn, address tokenOut, uint256 amountIn) external view returns (uint256 amountOut);
    function isActive(address tokenIn, address tokenOut) external view returns (bool active);
    function getPairs() external view returns (IPropAMM.TokenPair[] memory pairs);
    function paused() external view returns (bool);

    /// Best bid and ask in USDC native units (6 decimals) for an asset.
    /// Convenience proxy to IPricing.bbbo().
    function bbbo(uint8 assetId) external view returns (uint256 bestBid, uint256 bestAsk);
}

