pragma solidity ^0.8.24;

interface IBopAmmRouter {
    event FeeCharged(address indexed token, address indexed integrator, uint256 integratorFee, uint256 protocolFee);
    event FeeReceiverUpdated(address indexed feeReceiver);
    event FeePercentageUpdated(uint256 feePercentage);
    event AdapterUpdated(address indexed adapter, bool allowed);
    event SwapFallback(
        address indexed user,
        address indexed adapter,
        address indexed tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 amountOut
    );

    error OnlySelf();
    error Expired();
    error InvalidPair();
    error InvalidFee();
    error InvalidFeeReceiver();
    error InvalidMsgValue();
    error AdapterNotAllowed(address adapter);
    error EthTransferFailed();

    function NATIVE_ETH() external pure returns (address);
    function WETH() external view returns (address);

    function swapWithAllowance(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline,
        uint256 fee
    ) external payable returns (uint256 amountOut);

    function swapWithFallback(
        address tokenIn,
        address tokenOut,
        uint256 amountIn,
        uint256 minAmountOut,
        address recipient,
        uint256 deadline,
        address adapter,
        bytes calldata adapterData,
        uint256 fee
    ) external payable returns (uint256 amountOut, bool usedFallback);

    function setAdapter(address adapter, bool allowed) external;
    function setFeeReceiver(address newFeeReceiver) external;
    function setFeePercentage(uint256 newFeePercentage) external;
    function feeReceiver() external view returns (address);
    function feePercentage() external view returns (uint256);
    function allowedAdapters(address adapter) external view returns (bool);
    function pause() external;
    function unpause() external;
}

